import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;
import java.util.stream.Collectors;

class Solution {
    public static List<Integer> mergeSort(List<Integer> arr) {
        List<Integer> result = new ArrayList<>(arr);
        List<Integer> buffer = new ArrayList<>(arr);
        sort(result, buffer, 0, result.size());
        return result;
    }

    // Sort the half-open range [start, end).
    private static void sort(List<Integer> arr, List<Integer> buffer, int start, int end) {
        if (end - start <= 1) return;
        int mid = start + (end - start) / 2;
        sort(arr, buffer, start, mid);
        sort(arr, buffer, mid, end);

        int left = start;
        int right = mid;
        for (int i = start; i < end; i++) {
            if (left < mid && (right == end || arr.get(left) <= arr.get(right))) {
                buffer.set(i, arr.get(left++));
            } else {
                buffer.set(i, arr.get(right++));
            }
        }
        for (int i = start; i < end; i++) arr.set(i, buffer.get(i));
    }

    public static List<String> splitWords(String s) {
        return s.isEmpty() ? List.of() : Arrays.asList(s.split(" "));
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        List<Integer> arr = splitWords(scanner.nextLine()).stream().map(Integer::parseInt).collect(Collectors.toList());
        scanner.close();
        List<Integer> res = mergeSort(arr);
        System.out.println(res.stream().map(String::valueOf).collect(Collectors.joining(" ")));
    }
}
